{"file_path":"/app/pystan_analysis.py","content":"#!/usr/bin/env python3
"""PyStan 3.10.0 port of /app/gp_rstan.R.

Runs the same Bayesian GP-ARD regression model as the original R script,
using functionally equivalent Stan code, data, and posterior sampling
hyperparameters.  Posterior means of ``alpha``, ``sigma``, ``rho`` and
``beta`` are written to CSV files.
"""

import json

import numpy as np
import pandas as pd
import stan

# ---------------------------------------------------------------------------
# Stan model (functionally equivalent to the model in the R script)
# ---------------------------------------------------------------------------
STAN_CODE = """
functions {
  matrix cov_ard_sqexp(matrix X, vector rho, real alpha, real jitter) {
    int N = rows(X);
    int D = cols(X);
    matrix[N, N] K;

    for (i in 1:N) {
      K[i, i] = square(alpha) + jitter;
      for (j in (i + 1):N) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X[j, d]) / rho[d];
          s += t * t;
        }
        K[i, j] = square(alpha) * exp(-0.5 * s);
        K[j, i] = K[i, j];
      }
    }
    return K;
  }

  matrix cross_cov_ard(matrix X, matrix X_new, vector rho, real alpha) {
    int N = rows(X);
    int M = rows(X_new);
    int D = cols(X); // == cols(X_new)
    matrix[N, M] Kx;
    for (i in 1:N) {
      for (j in 1:M) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X_new[j, d]) / rho[d];
          s += t * t;
        }
        Kx[i, j] = square(alpha) * exp(-0.5 * s);
      }
    }
    return Kx;
  }
}

data {
  int<lower=1> N;
  int<lower=1> D;
  matrix[N, D] X;
  int<lower=1> P;
  matrix[N, P] H;
  vector[N] y;
  real<lower=0> jitter;

  int<lower=0> N_new;
  matrix[N_new, D] X_new;
  matrix[N_new, P] H_new;
}

parameters {
  vector[P] beta;
  real<lower=0> alpha;
  vector<lower=0>[D] rho;
  real<lower=0> sigma;
}

transformed parameters {
  vector[N] mu = H * beta;
  matrix[N, N] K = cov_ard_sqexp(X, rho, alpha, jitter)
                   + diag_matrix(rep_vector(square(sigma), N));
  matrix[N, N] L_K = cholesky_decompose(K);
}

model {
  beta  ~ normal(0, 1);
  alpha ~ normal(0, 1.5);
  rho   ~ lognormal(0, 1);
  sigma ~ normal(0, 0.5);
  y ~ multi_normal_cholesky(mu, L_K);
}

generated quantities {
  vector[N_new] y_new;
  if (N_new > 0) {
    matrix[N, N_new] K_x_xnew = cross_cov_ard(X, X_new, rho, alpha);
    matrix[N_new, N_new] K_new = cov_ard_sqexp(X_new, rho, alpha, jitter);
    vector[N] resid = y - (H * beta);

    vector[N] alpha_vec = mdivide_left_tri_low(L_K, resid);
    alpha_vec = mdivide_left_tri_low(L_K', alpha_vec);

    vector[N_new] f_mean = (K_x_xnew' * alpha_vec);
    matrix[N, N_new] v = mdivide_left_tri_low(L_K, K_x_xnew);
    vector[N_new] f_var = to_vector(diagonal(K_new)) - to_vector(columns_dot_self(v));
    for (m in 1:N_new) {
      real m_mean = (H_new[m] * beta) + f_mean[m];
      real m_sd   = sqrt(f_var[m] + square(sigma));
      y_new[m] = normal_rng(m_mean, m_sd);
    }
  }
}
"""


def main() -> None:
    # -----------------------------------------------------------------------
    # Load the same data files as the R script
    # -----------------------------------------------------------------------
    with open("/app/meta_public.json", "r") as fh:
        meta_pub = json.load(fh)

    train_X = pd.read_csv("/app/train_X.csv", header=0).to_numpy(dtype=float)
    test_X = pd.read_csv("/app/test_X.csv", header=0).to_numpy(dtype=float)
    train_y = pd.read_csv("/app/train_y.csv", header=0)["y"].to_numpy(dtype=float)

    P = int(meta_pub["P"])
    jitter = float(meta_pub["jitter"])

    N, D = train_X.shape
    N_new = test_X.shape[0]

    # H uses the first two columns of X plus an intercept, as in the R script.
    H = np.column_stack([np.ones(N), train_X[:, 0], train_X[:, 1]])
    if N_new > 0:
        H_new = np.column_stack([np.ones(N_new), test_X[:, 0], test_X[:, 1]])
    else:
        H_new = np.zeros((0, P))

    data_list = {
        "N": N,
        "D": D,
        "X": train_X,
        "P": P,
        "H": H,
        "y": train_y,
        "jitter": jitter,
        "N_new": N_new,
        "X_new": test_X if N_new > 0 else np.zeros((0, D)),
        "H_new": H_new if N_new > 0 else np.zeros((0, P)),
    }

    # -----------------------------------------------------------------------
    # Build the model and draw posterior samples.
    #
    # Sampling setup (functionally equivalent to the R script):
    #   chains = 4, iter = 2000, warmup = 1000, thin = 2
    #   seed   = 1  (set via stan.build's random_seed)
    #   control = list(adapt_delta = 0.93, max_treedepth = 14,
    #                  adapt_gamma = 0.05, adapt_kappa = 0.75,
    #                  adapt_t0 = 10, adapt_init_buffer = 100,
    #                  adapt_term_buffer = 50, adapt_window = 25)
    #   init_r = 0.1, save_warmup = FALSE, refresh = 200
    # -----------------------------------------------------------------------
    posterior = stan.build(STAN_CODE, data=data_list, random_seed=1)

    fit = posterior.sample(
        num_chains=4,
        num_warmup=1000,
        num_samples=1000,
        num_thin=2,
        save_warmup=False,
        init_radius=0.1,
        refresh=200,
        max_depth=14,
        delta=0.93,
        gamma=0.05,
        kappa=0.75,
        t0=10,
        init_buffer=100,
        term_buffer=50,
        window=25,
    )

    # -----------------------------------------------------------------------
    # Extract posterior samples and compute posterior means
    # -----------------------------------------------------------------------
    alpha_post = float(np.mean(fit["alpha"]))
    sigma_post = float(np.mean(fit["sigma"]))
    rho_post = np.mean(fit["rho"], axis=1)      # length-D vector of means
    beta_post = np.mean(fit["beta"], axis=1)    # length-P vector of means

    print("Posterior means:")
    print("alpha:", alpha_post)
    print("sigma:", sigma_post)
    print("rho:  ", " ".join(f"{x:.6f}" for x in rho_post))
    print("beta: ", " ".join(f"{x:.6f}" for x in beta_post))

    # -----------------------------------------------------------------------
    # Save results (numeric values only)
    # -----------------------------------------------------------------------
    np.savetxt("/app/alpha_est.csv", np.asarray([alpha_post]), fmt="%.17g")
    np.savetxt("/app/sigma_est.csv", np.asarray([sigma_post]), fmt="%.17g")
    np.savetxt("/app/rho_est.csv", np.asarray(rho_post), fmt="%.17g")
    np.savetxt("/app/beta_est.csv", np.asarray(beta_post), fmt="%.17g")


if __name__ == "__main__":
    main()
"}
